if doc.workflow_state == "Approved From Customer":
    attachments = frappe.get_all(
        "File",
        filters={
            "attached_to_doctype": doc.doctype,
            "attached_to_name": doc.name,
            "is_folder": 0,
            "attached_to_field": ""  # ← change is here
        },
        fields=["name"]
    )
    len_off_attchement = len(attachments)
    if len_off_attchement < 1:
        frappe.throw(f"📎 Attachment is missing. {len_off_attchement}")
